#!/usr/bin/env node
/*
 * Obiter — AGLC4 Word Add-in
 * Copyright (C) 2026. Licensed under GPLv3.
 *
 * TRUST-002: Generate the nginx security-header snippets for /app/ from the
 * single source of truth in config/csp.js. NEVER hand-edit the generated
 * .conf files — edit config/csp.js and re-run this script:
 *
 *   node scripts/generate-nginx-headers.js
 *
 * Outputs (committed to the repo, regenerated by the deploy scripts so they
 * can never drift from config/csp.js):
 *   scripts/nginx/app-security-headers.conf              — enforced (production /app/)
 *   scripts/nginx/app-security-headers.report-only.conf  — Report-Only (beta /app/beta/ staged rollout)
 */

"use strict";

const fs = require("fs");
const path = require("path");

const { CSP_HEADER_POLICY } = require("../config/csp.js");

// The policy is emitted inside a double-quoted nginx string. It must not
// contain characters that would break out of that context.
if (/["\\\n\r]/.test(CSP_HEADER_POLICY)) {
  console.error(
    "generate-nginx-headers: CSP_HEADER_POLICY contains a character (\" \\ or newline) " +
      "that is unsafe inside a double-quoted nginx add_header value. Fix config/csp.js."
  );
  process.exit(1);
}
if (!CSP_HEADER_POLICY.includes("frame-ancestors")) {
  console.error(
    "generate-nginx-headers: CSP_HEADER_POLICY is missing frame-ancestors — " +
      "the header variant must include it (see config/csp.js buildCsp)."
  );
  process.exit(1);
}

const OUT_DIR = path.join(__dirname, "nginx");

/**
 * Shared non-CSP headers (identical in both variants).
 * `always` ensures the headers are also sent on error responses.
 */
const COMMON_HEADERS = [
  'add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;',
  'add_header X-Content-Type-Options "nosniff" always;',
  'add_header Referrer-Policy "strict-origin-when-cross-origin" always;',
];

const NO_XFO_NOTE = `# Deliberately NO X-Frame-Options header: Office on the web embeds the task
# pane in iframes served from multiple Microsoft hosts (*.officeapps.live.com,
# *.office.com, *.microsoft365.com, *.cloud.microsoft, *.sharepoint.com).
# X-Frame-Options cannot allowlist multiple origins and would break Word on
# the web; the CSP frame-ancestors directive above is the correct mechanism.`;

/**
 * Build one snippet.
 *
 * @param {string} cspHeaderName "Content-Security-Policy" or
 *   "Content-Security-Policy-Report-Only"
 * @param {string} purpose comment line describing the variant
 * @param {string} includeExample the include line for the target location block
 * @returns {string}
 */
function buildSnippet(cspHeaderName, purpose, includeExample) {
  return `# GENERATED FILE — DO NOT EDIT.
# Source of truth: config/csp.js (CSP_HEADER_POLICY).
# Regenerate with: node scripts/generate-nginx-headers.js
#
# TRUST-002: ${purpose}
# Intended for \`include\` inside the nginx location block that serves the
# add-in (one-time manual step, see docs/server-setup.md):
#   ${includeExample}

add_header ${cspHeaderName} "${CSP_HEADER_POLICY}" always;
${COMMON_HEADERS.join("\n")}

${NO_XFO_NOTE}
`;
}

const enforced = buildSnippet(
  "Content-Security-Policy",
  "enforced security headers for production /app/.",
  "include /opt/bitnami/nginx/conf/obiter/app-security-headers.conf;"
);

const reportOnly = buildSnippet(
  "Content-Security-Policy-Report-Only",
  "Report-Only variant for the /app/beta/ staged rollout. The CSP is\n" +
    "# observe-only (violations logged to the browser console, nothing blocked);\n" +
    "# HSTS/nosniff/Referrer-Policy are enforced in both variants.",
  "include /opt/bitnami/nginx/conf/obiter/app-security-headers.beta.conf;"
);

fs.mkdirSync(OUT_DIR, { recursive: true });

const outputs = [
  ["app-security-headers.conf", enforced],
  ["app-security-headers.report-only.conf", reportOnly],
];

for (const [name, content] of outputs) {
  const file = path.join(OUT_DIR, name);
  fs.writeFileSync(file, content);
  console.log("wrote " + path.relative(process.cwd(), file));
}
